text:
{
  "tasks": [
    {
      "task_id": "T01",
      "title": "2026年每月任务数量统计",
      "business_question": "统计2026年每个月创建的任务数量，并按月份升序排列。",
      "priority": "P0",
      "priority_reason": "核心需求：直接回答“2026年每月创建的任务数量”这一分析目标。若删除此任务，无法提供按月份分布的任务计数及排序结果，导致核心问题无法回答。",
      "requirement_ids": [
        "C01",
        "C02",
        "C03",
        "C04"
      ],
      "depends_on": [],
      "missing_inputs": [],
      "steps": [
        {
          "step_id": "S01",
          "operation": "derive",
          "params": {
            "function": "extract_year",
            "field": "field_0001",
            "alias": "year_created"
          }
        },
        {
          "step_id": "S02",
          "operation": "filter",
          "params": {
            "conditions": [
              {
                "field": "year_created",
                "operator": "eq",
                "value": 2026
              }
            ]
          }
        },
        {
          "step_id": "S03",
          "operation": "derive",
          "params": {
            "function": "extract_month",
            "field": "field_0001",
            "alias": "month_created"
          }
        },
        {
          "step_id": "S04",
          "operation": "group_aggregate",
          "params": {
            "metrics": [
              {
                "function": "count",
                "field": null,
                "alias": "task_count"
              }
            ],
            "dimensions": [
              "month_created"
            ]
          }
        },
        {
          "step_id": "S05",
          "operation": "sort",
          "params": {
            "field": "month_created",
            "direction": "asc"
          }
        }
      ]
    }
  ]
}
